(() => {
  const key='birga-catalog-v1';
  const categories=['Elektronika','Kiyimlar','Uy va ro‘zg‘or','Go‘zallik','Sport','Bolalar'];
  const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function image(value){if(/^photo-[\w-]+$/.test(value))return `https://images.unsplash.com/${value}?w=600&auto=format&fit=crop&q=80`;try{const url=new URL(value);if(url.protocol==='https:')return url.href}catch{}return 'data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 width=%22100%22 height=%22100%22%3E%3Crect width=%22100%22 height=%22100%22 fill=%22%23edf0e5%22/%3E%3C/svg%3E'}
  function validate(p){if(!p.name||typeof p.name!=='string'||!p.name.trim()||p.name.length>160)throw Error('Mahsulot nomini kiriting (160 belgigacha).');if(!categories.includes(p.cat))throw Error('Kategoriyani tanlang.');if(!Number.isSafeInteger(p.price)||p.price<1||p.price>1e12)throw Error('Narx musbat butun son bo‘lishi kerak.');if(!Number.isSafeInteger(p.old)||p.old<0||p.old>1e12||(p.old&&p.old<p.price))throw Error('Eski narx yangi narxdan kichik bo‘la olmaydi.');if(!Number.isSafeInteger(p.stock)||p.stock<0||p.stock>1e6)throw Error('Ombor qoldig‘i 0 dan 1 000 000 gacha bo‘lishi kerak.');if(typeof p.img!=='string'||p.img.length>1500||(!/^photo-[\w-]+$/.test(p.img)&&!/^https:\/\//i.test(p.img)))throw Error('Rasm uchun HTTPS havola kiriting.');if(typeof p.desc!=='string'||p.desc.length>2000)throw Error('Tavsif 2000 belgidan oshmasligi kerak.');}
  function defaults(){return window.BIRGA_SEEDS.map((p,i)=>({...p,active:true,stock:[24,4,68,15,3,8,32,0,21,5,17,29][i]??0}))}
  function list(){try{const raw=localStorage.getItem(key);if(raw===null)return defaults();const rows=JSON.parse(raw);if(!Array.isArray(rows))return defaults();const ids=new Set();for(const row of rows){validate(row);if(!Number.isSafeInteger(row.id)||row.id<1||ids.has(row.id)||typeof row.active!=='boolean')return defaults();ids.add(row.id)}return rows}catch{return defaults()}}
  function persist(rows){try{localStorage.setItem(key,JSON.stringify(rows))}catch{throw Error('Saqlab bo‘lmadi. Brauzer xotirasiga ruxsatni tekshiring.')}window.dispatchEvent(new Event('catalogchange'));return rows}
  function upsert(input){const rows=list(),existing=input.id?rows.find(p=>p.id===input.id):null;if(input.id&&!existing)throw Error('Mahsulot topilmadi. Sahifani yangilang.');const p={...existing,...input,id:existing?.id??Math.max(0,...rows.map(p=>p.id))+1,rating:existing?.rating??0,reviews:existing?.reviews??0,name:input.name.trim(),desc:input.desc.trim()};validate(p);p.badge=p.old>p.price?`−${Math.round((1-p.price/p.old)*100)}%`:'YANGI';if(existing)rows[rows.findIndex(row=>row.id===existing.id)]=p;else rows.push(p);persist(rows);return p}
  function remove(id){const rows=list();if(!rows.some(p=>p.id===id))throw Error('Mahsulot topilmadi.');persist(rows.filter(p=>p.id!==id))}
  window.Catalog={key,categories,list,upsert,remove,image,escape};
})();
